from fractions import Fraction
from math import gcd,sqrt
from collections import deque
def lcm(a,b):return a*b//gcd(a,b)
def tok(d):
 q=[Fraction(str(abs(x))) for x in d];z=sum(q)
 if z==0:return None
 n=len(d);return [(Fraction(i,n),1 if x>0 else -1 if x<0 else 0,q[i]/z) for i,x in enumerate(d)]
def mono(x,z):
 i=j=0;rx=x[0][2];rz=z[0][2];cd=Fraction(0);ct=Fraction(0)
 while i<len(x) and j<len(z):
  m=min(rx,rz);cd+=m*(x[i][1]!=z[j][1]);ct+=m*abs(x[i][0]-z[j][0]);rx-=m;rz-=m
  if rx==0:i+=1;rx=x[i][2] if i<len(x) else 0
  if rz==0:j+=1;rz=z[j][2] if j<len(z) else 0
 return cd,ct
def lex(x,z):
 den=1
 for q in [t[2] for t in x+z]:den=lcm(den,q.denominator)
 N=2+len(x)+len(z);src=0;sink=N-1;g=[[] for _ in range(N)]
 def add(u,v,c,w):g[u].append([v,c,w,len(g[v]),0]);g[v].append([u,0,-w,len(g[u])-1,0])
 for i,t in enumerate(x):add(src,1+i,int(t[2]*den),0)
 refs=[];BIG=10*den
 for i,a in enumerate(x):
  for j,b in enumerate(z):
   u=1+i;k=len(g[u]);add(u,1+len(x)+j,den,BIG*(a[1]!=b[1])+abs(i-j));refs.append((u,k,i,j))
 for j,t in enumerate(z):add(1+len(x)+j,sink,int(t[2]*den),0)
 flow=0
 while flow<den:
  dist=[10**30]*N;prev=[None]*N;inq=[False]*N;dist[src]=0;Q=deque([src]);inq[src]=True
  while Q:
   u=Q.popleft();inq[u]=False
   for k,e in enumerate(g[u]):
    if e[1]>0 and dist[e[0]]>dist[u]+e[2]:
     dist[e[0]]=dist[u]+e[2];prev[e[0]]=(u,k)
     if not inq[e[0]]:Q.append(e[0]);inq[e[0]]=True
  aug=den-flow;v=sink
  while v!=src:u,k=prev[v];aug=min(aug,g[u][k][1]);v=u
  v=sink
  while v!=src:u,k=prev[v];e=g[u][k];e[1]-=aug;e[4]+=aug;g[v][e[3]][1]+=aug;v=u
  flow+=aug
 cd=Fraction(0);ct=Fraction(0)
 for u,k,i,j in refs:
  f=g[u][k][4];cd+=Fraction(f,den)*(x[i][1]!=z[j][1]);ct+=Fraction(f,den)*abs(x[i][0]-z[j][0])
 return cd,ct
def shift(t):
 n=len(t);d=n//2;v=[(q[1],q[2]) for q in t];v=v[d:]+v[:d];return [(t[i][0],v[i][0],v[i][1]) for i in range(n)]
def levels(d):
 a=[0.]
 for q in d:a.append(a[-1]+q)
 return a
def corr(x,y):
 mx=sum(x)/len(x);my=sum(y)/len(y);return sum((a-mx)*(b-my) for a,b in zip(x,y))/sqrt(sum((a-mx)**2 for a in x)*sum((b-my)**2 for b in y))
